  "recovered_c": "uint64_t fn_14(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < (len + 2) / 3 << 2) {\n    return VERA_ERR;\n  }\n\n  size_t o = 0;\n  for (size_t i = 0; i + 3 <= len; i += 3) {\n    uint32_t w = (uint)in[i] << 16 | (uint)in[i + 1] << 8 | (uint)in[i + 2];\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[in[i] >> 2];\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[(w & 0x3f000) >> 12];\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[(w & 0xfc0) >> 6];\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[w & 0x3f];\n  }\n\n  if (len - i == 1) {\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[in[i] >> 2];\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[(in[i] & 3) << 4];\n    out[o++] = '=';\n    out[o++] = '=';\n  } else if (len - i == 2) {\n    uint32_t w = (uint)in[i] << 16 | (uint)in[i + 1] << 8;\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[in[i] >> 2];\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[(w & 0x3f000) >> 12];\n    out[o++] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\"[(w & 0xfc0) >> 6];\n    out[o++] = '=';\n  }\n\n  return o;\n}"
